INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17573$nota-0165$m17573$, $m17574$Manual treinamento.pdf$m17574$, $m17575$71$m17575$, $m17576$Em atletas iniciantes, aumentos superiores a 20% são relativamente comuns. Em atletas de elite, ganhos de apenas 2 ou 3% podem representar enorme evolução competitiva. Por isso, em níveis elevados, o foco do treinamento frequentemente desloca-se do aumento do VO₂máx para a melhoria da economia, dos limiares e da durabilidade.$m17576$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17577$nota-0165$m17577$, $m17578$nota-0162$m17578$, $m17579$pre-requisito$m17579$, $m17580$as adaptações centrais/periféricas descritas aqui correspondem diretamente aos dois componentes da Equação de Fick (nota-0162)$m17580$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17581$nota-0179$m17581$, $m17582$Manual treinamento.pdf$m17582$, $m17583$91$m17583$, $m17584$Economia: refere-se ao custo energético para manter determinada intensidade de exercício... Eficiência Mecânica: representa a proporção da energia metabólica convertida em trabalho mecânico útil. Eficiência = Trabalho Mecânico ÷ Energia Metabólica. No ciclismo, a eficiência mecânica costuma variar entre aproximadamente 20 e 25%.$m17584$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17585$nota-0179$m17585$, $m17586$nota-0230$m17586$, $m17587$refinada-por$m17587$, $m17588$nota-0230 (McArdle) especifica que a faixa 20-25% citada aqui vale para ciclismo estacionário (sem arrasto); no ciclismo de estrada — a modalidade relevante para o produto — a eficiência cai abaixo de 20% por causa do arrasto aerodinâmico. Ver ressalva no corpo.$m17588$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17589$nota-0205$m17589$, $m17590$VO2 Max Essentials_Final.pdf$m17590$, $m17591$7$m17591$, $m17592$There is an incredible amount of evidence indicating that your VO2 max can predict your risk for cardiovascular disease and even death... it's been shown that increasing your VO2 max by just 3.5 ml/kg/min (referred to as a 1 metabolic equivalent of task or MET) reduces the risk for all-cause mortality by 11%. [Laukkanen JA, Isiozor NM, Kunutsor SK. Objectively assessed cardiorespiratory fitness and all-cause mortality risk. Mayo Clinic Proceedings. 2022;97(6):1054-1073.] ... individuals who ranked in the top one-third of aerobic fitness had a 45% reduced risk for all-cause mortality compared to individuals in the lower one-third.$m17592$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17593$nota-0205$m17593$, $m17594$nota-0163$m17594$, $m17595$complementa$m17595$, $m17596$acrescenta a motivação de saúde/longevidade por trás da tabela de referência de VO2máx já registrada na nota-0163 (Fonte 2)$m17596$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17597$nota-0210$m17597$, $m17598$VO2 Max Essentials_Final.pdf$m17598$, $m17599$21$m17599$, $m17600$The primary factors that limit VO2 max can be classified as either central factors, which include the pulmonary diffusing capacity, maximal cardiac output, and oxygen-carrying capacity of the blood, or peripheral factors including skeletal muscle characteristics.$m17600$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17601$nota-0210$m17601$, $m17602$VO2 Max Essentials_Final.pdf$m17602$, $m17603$24$m17603$, $m17604$the dominant factor limiting VO2 max in whole-body exercise appears to be maximal cardiac output, while for exercise with small muscle groups, the role of cardiac output is considerably less important. The current belief is that maximal cardiac output is the principal limiting factor for VO2 max.$m17604$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17605$nota-0210$m17605$, $m17606$nota-0162$m17606$, $m17607$complementa$m17607$, $m17608$detalha os componentes central/periférico da Equação de Fick já registrada na nota-0162 (Fonte 2), com o consenso científico sobre qual domina$m17608$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17609$nota-0211$m17609$, $m17610$VO2 Max Essentials_Final.pdf$m17610$, $m17611$23$m17611$, $m17612$mitochondria don't appear to be the main limiter for VO2 max, as doubling the number of mitochondria should theoretically double the number of sites for oxygen uptake in muscle (and double VO2 max).$m17612$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17613$nota-0211$m17613$, $m17614$VO2 Max Essentials_Final.pdf$m17614$, $m17615$24$m17615$, $m17616$studies show that there is only a modest increase in V̇O2 max (20%–40%) even when mitochondria increase more than two-fold. This is consistent with the view that V̇O2 max is limited by oxygen delivery and not muscle mitochondria. The main effect of increasing mitochondrial enzymes is to improve endurance performance rather than to increase V̇O2 max... 1) muscles will oxidize fat at a higher rate (thus sparing muscle glycogen and blood glucose) and 2) decreased lactate production during exercise.$m17616$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17617$nota-0211$m17617$, $m17618$nota-0210$m17618$, $m17619$pre-requisito$m17619$, $m17620$detalha, dentro dos fatores periféricos já descritos na nota-0210, por que as mitocôndrias não são o principal limitante do VO2máx$m17620$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17621$nota-0211$m17621$, $m17622$nota-0156$m17622$, $m17623$complementa$m17623$, $m17624$explica o mecanismo mitocondrial por trás da flexibilidade metabólica já registrada na nota-0156 (Fonte 2)$m17624$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17625$nota-0213$m17625$, $m17626$VO2 Max Essentials_Final.pdf$m17626$, $m17627$28$m17627$, $m17628$the relative contribution of anaerobic metabolism is small during marathon running but becomes significant in events lasting 10–30 minutes, such as 5 km and 10 km running. Anaerobic metabolism may contribute approximately 10%–20% of total ATP turnover during these shorter endurance events.$m17628$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17629$nota-0213$m17629$, $m17630$VO2 Max Essentials_Final.pdf$m17630$, $m17631$28$m17631$, $m17632$High skeletal muscle capillary density is also important, as it helps remove or recycle fatiguing metabolites, such as hydrogen ions, within the muscles... enhance the tolerance of anaerobic metabolism and lactate production, allowing for improved endurance performance and a higher performance VO2.$m17632$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17633$nota-0213$m17633$, $m17634$nota-0126$m17634$, $m17635$complementa$m17635$, $m17636$fornece uma faixa percentual de referência (10-20%) para a contribuição anaeróbia em esforços de 10-30min, complementando a estimativa de contribuição aeróbia/anaeróbia via MAOD já registrada na nota-0126 do Livro 1$m17636$)
